package com.ke.ticketsystemke.service;import com.ke.ticketsystemke.dto.*;import com.ke.ticketsystemke.entity.*;import com.ke.ticketsystemke.repository.*;import org.junit.jupiter.api.*;import org.junit.jupiter.api.extension.ExtendWith;import org.mockito.*;import org.mockito.junit.jupiter.MockitoExtension;import org.springframework.test.util.ReflectionTestUtils;import java.time.*;import java.util.*;import static org.assertj.core.api.Assertions.*;import static org.mockito.Mockito.*;
@ExtendWith(MockitoExtension.class)class WarrantyReportServiceTest{@Mock WarrantyClaimRepository claims;@Mock WarrantyReplacementRepository replacements;@Mock WarrantyAttachmentRepository attachments;@Mock EmployeeRepository employees;@Mock AccessService access;@Mock WarrantyDocumentRequirementService documents;WarrantyReportService service;LocalDate today=LocalDate.now(ZoneId.of("Asia/Kolkata"));
@BeforeEach void setup(){service=new WarrantyReportService(claims,replacements,attachments,employees,access,new WarrantyPendingActionCalculator(),documents);lenient().when(replacements.findByWarrantyClaim_IdIn(any())).thenReturn(List.of());lenient().when(attachments.findActiveCategoriesByClaimIds(any())).thenReturn(List.of());lenient().when(employees.findByEmployeeIdLowercaseIn(any())).thenReturn(List.of());}
@Test void outcomesUseResolvedDenominatorAndExplicitMilestones(){WarrantyClaim repaired=claim(1,WarrantyClaimResult.MANUFACTURER_REPAIR_DONE,10),replaced=claim(2,WarrantyClaimResult.REPLACEMENT_DONE,20),pending=claim(3,WarrantyClaimResult.PENDING,null);when(claims.findAllForTracker()).thenReturn(List.of(repaired,replaced,pending));WarrantyReportFilter f=range(30);Map<String,Object>d=service.outcomes(f,"ADMIN").data();assertThat(d.get("resolvedClaims")).isEqualTo(2L);List<Map<String,Object>> rows=(List<Map<String,Object>>)d.get("outcomes");assertThat(rows.stream().filter(x->x.get("outcome").equals("MANUFACTURER_REPAIR_DONE")).findFirst().orElseThrow().get("percentage")).isEqualTo(50.0);}
@Test void resolutionAverageMedianBucketsAndSamplesAreCorrect(){WarrantyClaim a=claim(1,WarrantyClaimResult.MANUFACTURER_REPAIR_DONE,2),b=claim(2,WarrantyClaimResult.WARRANTY_REJECTED,8);when(claims.findAllForTracker()).thenReturn(List.of(a,b));Map<String,Object>d=service.resolutionTimes(range(30),"ADMIN").data(),overall=(Map<String,Object>)d.get("overall");assertThat(overall.get("average")).isEqualTo(5.0);assertThat(overall.get("median")).isEqualTo(5.0);assertThat(overall.get("sampleSize")).isEqualTo(2);List<Map<String,Object>> buckets=(List<Map<String,Object>>)d.get("buckets");assertThat(buckets.stream().mapToLong(x->((Number)x.get("count")).longValue()).sum()).isEqualTo(2);}
@Test void visitDelayNeverBecomesNegativeAndMissingFollowUpMilestoneIsExplicit(){WarrantyClaim c=claim(1,WarrantyClaimResult.PENDING,null);c.setExpectedVisitDate(today);c.setActualVisitDate(today.minusDays(1));when(claims.findAllForTracker()).thenReturn(List.of(c));Map<String,Object>d=service.followUpVisits(range(30),"ADMIN").data(),visit=(Map<String,Object>)d.get("visitDelay"),follow=(Map<String,Object>)d.get("followUpDelay");assertThat(visit.get("average")).isEqualTo(0.0);assertThat(follow.get("available")).isEqualTo(false);assertThat(follow.get("average")).isNull();}
@Test void replacementStagesAndDurationsRemainSeparate(){WarrantyClaim c=claim(1,WarrantyClaimResult.REPLACEMENT_DONE,10);c.setReplacementApprovalDate(today.minusDays(8));c.setReplacementApprovedAt(today.minusDays(8).atStartOfDay(ZoneId.of("Asia/Kolkata")).toInstant());WarrantyReplacement r=new WarrantyReplacement();r.setWarrantyClaim(c);r.setActive(true);r.setReplacementReceivedDate(today.minusDays(5));r.setReplacementGivenToCustomerDate(today.minusDays(2));when(claims.findAllForTracker()).thenReturn(List.of(c));when(replacements.findByWarrantyClaim_IdIn(any())).thenReturn(List.of(r));Map<String,Object>d=service.replacement(range(30),"ADMIN").data();assertThat(((Map<?,?>)d.get("approvalToReceipt")).get("average")).isEqualTo(3.0);assertThat(((Map<?,?>)d.get("receiptToDelivery")).get("average")).isEqualTo(3.0);}
@Test void ownerAndDocumentReportsIncludeUnassignedAndOverrides(){WarrantyClaim c=claim(1,WarrantyClaimResult.PENDING,null);c.setWarrantyOwnerEmployeeId(null);c.setBillDocumentOverrideReason("Bill unavailable");when(claims.findAllForTracker()).thenReturn(List.of(c));when(documents.billRuleApplies(c)).thenReturn(true);Map<String,Object>owner=service.owners(range(30),"ADMIN").data(),docs=service.documentReadiness(range(30),"ADMIN").data();assertThat(((List<Map<String,Object>>)owner.get("owners")).getFirst().get("ownerName")).isEqualTo("Unassigned");assertThat(docs.get("claimsMissingRequired")).isEqualTo(1L);assertThat(docs.get("claimsUsingBillOverride")).isEqualTo(1L);}
@Test void trendsIncludeZeroPeriodsAndValidateRange(){when(claims.findAllForTracker()).thenReturn(List.of());WarrantyReportFilter f=range(3);Map<String,Object>d=service.trends(f,"ADMIN").data();assertThat(d.get("grouping")).isEqualTo("DAILY");assertThat((List<?>)d.get("periods")).hasSize(3);f.setFrom(today.minusYears(6));assertThatThrownBy(()->service.summary(f,"ADMIN")).hasMessageContaining("400");}
@Test void reportPermissionIsIndependentAndFailClosed(){doNothing().when(access).requireAllowed("USER",AccessKey.VIEW_TICKETS);doThrow(new org.springframework.web.server.ResponseStatusException(org.springframework.http.HttpStatus.FORBIDDEN,"denied")).when(access).requireAllowed("USER",AccessKey.VIEW_WARRANTY_REPORTS);assertThatThrownBy(()->service.summary(range(30),"USER")).hasMessageContaining("403");verifyNoInteractions(claims);}
private WarrantyReportFilter range(int days){WarrantyReportFilter f=new WarrantyReportFilter();f.setFrom(today.minusDays(days-1));f.setTo(today);return f;}private WarrantyClaim claim(long id,WarrantyClaimResult result,Integer duration){Ticket t=new Ticket();t.setId(id);t.setTicketNumber("KE-"+id);t.setCustomerName("Customer");t.setMobileNumber("9999999999");t.setProductType("TV");t.setStatus(TicketStatus.IN_PROGRESS);WarrantyClaim c=new WarrantyClaim();ReflectionTestUtils.setField(c,"id",id);Instant start=today.minusDays(duration==null?5:duration).atStartOfDay(ZoneId.of("Asia/Kolkata")).toInstant();ReflectionTestUtils.setField(c,"createdAt",start);ReflectionTestUtils.setField(c,"markedWarrantyAt",start);ReflectionTestUtils.setField(c,"updatedAt",Instant.now());c.setTicket(t);c.setClaimSequence(1);c.setActive(result==WarrantyClaimResult.PENDING);c.setState(result==WarrantyClaimResult.PENDING?WarrantyClaimState.COMPLAINT_REQUIRED:WarrantyClaimState.RESOLVED);c.setResult(result);c.setManufacturerName("Maker");c.setModelNumber("M1");c.setWarrantyOwnerEmployeeId("OWNER");if(duration!=null)c.setResolvedAt(today.atStartOfDay(ZoneId.of("Asia/Kolkata")).toInstant());return c;}}
